    if (buffer.isEmpty()) {
        // If the input stream is non-blocking, return 0
        if (isNonBlocking()) {
            return 0;
        }
        // Otherwise, block until data is available
        while (buffer.isEmpty()) {
            try {
                // Wait for data to be available
                synchronized (this) {
                    this.wait();
                }
            } catch (InterruptedException e) {
                throw new IOException("Interrupted while waiting for data", e);
            }
        }
    }
    // Return the number of available bytes in the input stream
    return buffer.size();
}

