    if (graph == null || vertices == null || vertices.isEmpty()) {
        return false;
    }

    int numVertices = vertices.size();
    int numEdges = 0;

    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 != v2 && !v1.equals(v2)) {
                if (graph.containsEdge(v1, v2)) {
                    numEdges++;
                }
            }
        }
    }

    return numEdges >= (numVertices * (numVertices - 1)) / 2;
}

