        return segments;
    }

    int start = 0;
    if (path.charAt(0) == '/') {
        start++;
    }

    int index = 0;
    while (index < path.length()) {
        int indexOfNextSlash = path.indexOf('/', index);
        if (indexOfNextSlash == -1) {
            indexOfNextSlash = path.length();
        }

        String segment = path.substring(start, indexOfNextSlash);
        if (decode) {
            try {
                segment = URLDecoder.decode(segment, "UTF-8");
            } catch (UnsupportedEncodingException e) {
                throw new URIException("Unable to decode path segment", e);
            }
        }

        segments.add(new PathSegmentImpl(segment));
        start = indexOfNextSlash + 1;
        index = start;
    }

    return segments;
}

