public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder result = new StringBuilder(str.length());

    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i == str.length() - 1) {
                throw new Exception("Invalid escape sequence at the end of the input");
            }
            char next = str.charAt(i + 1);
            if (next == '\'') {
                // Turn ''' into a single ' character
                result.append('\'');
            } else if (next == '"') {
                // Turn "" into a single " character
                result.append('"');
            } else if (next == '\\') {
                // Turn \\ into a single \ character
                result.append('\\');
            } else if (next == 'n') {
                // Turn \n into a newline character
                result.append('\n');
            } else if (next == 'r') {
                // Turn \r into a carriage return character
                result.append('\r');
            } else if (next == 't') {
                // Turn \t into a tab character
                result.append('\t');
            } else {
                // Unexpected escape sequence, throw an exception
                throw new Exception("Invalid escape sequence at index " + i);
            }
            i++; // Skip the next character as part of the escape sequence
        } else {
            result.append(c);
        }
    }

    return result.toString();
}

