public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
  if (genericType == null || targetType == null) {
    throw new IllegalArgumentException("genericType and targetType must not be null");
  }

  if (!(genericType instanceof ParameterizedType)) {
    return null;
  }

  ParameterizedType parameterizedType = (ParameterizedType) genericType;
  Type[] typeArgs = parameterizedType.getActualTypeArguments();
  if (typeArgs.length == 0) {
    return null;
  }

  Class<?>[] resolvedArgs = new Class<?>[typeArgs.length];
  for (int i = 0; i < typeArgs.length; i++) {
    Type typeArg = typeArgs[i];
    if (typeArg instanceof TypeVariable) {
      // Resolve the type variable
      TypeVariable<?> typeVariable = (TypeVariable<?>) typeArg;
      Type typeVariableBound = typeVariable.getBounds()[0];
      if (typeVariableBound instanceof ParameterizedType) {
        // Get the raw type of the parameterized type
        ParameterizedType parameterizedBound = (ParameterizedType) typeVariableBound;
        resolvedArgs[i] = parameterizedBound.getRawType();
      } else if (typeVariableBound instanceof Class) {
        // Get the class of the type variable bound
        resolvedArgs[i] = (Class<?>) typeVariableBound;
      } else {
        throw new IllegalArgumentException("Type variable bound must be a parameterized type or a class");
      }
    } else if (typeArg instanceof Class) {
      // Get the class of the type argument
      resolvedArgs[i] = (Class<?>) typeArg;
    } else {
      throw new IllegalArgumentException("Type argument must be a type variable or a class");
    }
  }

  return resolvedArgs;
}

