public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    int filenameStartIndex = path.lastIndexOf("/");
    int fileExtensionStartIndex = filenameStartIndex + 1;
    int fileExtensionEndIndex = path.lastIndexOf(".");
    if (fileExtensionStartIndex == filenameStartIndex || fileExtensionStartIndex >= fileExtensionEndIndex) {
        return path;
    }
    return path.substring(0, fileExtensionStartIndex) + path.substring(fileExtensionEndIndex + 1);
}

