    // Get a list of active nodes
    List<CategoryTreeNode> activeNodes = getActiveNodes();

    // Remove any inactive nodes
    for (CategoryTreeNode node : this.categoryTreeNodeSet) {
        if (!activeNodes.contains(node)) {
            node.setParent(null);
            this.categoryTreeNodeSet.remove(node);
        }
    }

    // Return the number of nodes removed
    return activeNodes.size() - this.categoryTreeNodeSet.size();
}

