    for (Field field : mappings.getFields()) {
        // Check if the field exists in the current index mappings
        if (!currentMappings.containsField(field.getName())) {
            // Add the field to the diff mappings
            diffMappings.addField(field);
        }
    }

    // Remove the _source configuration from the diff mappings
    diffMappings.getConfiguration().remove(Configuration.Source);

    // Return the diff mappings
    return diffMappings;
